attributes.staticValue:
var env;
var playWelcome = 'playWelcome';
var hangupAt = '';
var languageInput = '';
var playInvalidInput = 'playInvalidInput';
var playLanguage = 'playLanguage';
var playNoInput = 'playNoInput';
var language = '';
var playMainMenu = 'playMainMenu';
var mainMenuInput = '';
var routingOption = '';
var transferTo = '';

var env;
try {
    if (languageInput == '1') {
        language = 'english';
        playMainMenu = 'playMainMenu_en';
    } else if (languageInput == '2') {
        language = 'hindi';
        playMainMenu = 'playMainMenu_hi';
    } else {
        language = 'english';
        playMainMenu = 'playMainMenu_en';
    }
    env.info("Language selected: " + language);
    hangupAt = 'PostLanguageScript';
} catch(e) {
    env.info("Error in PostLanguageScript: " + e);
    language = 'english';
    playMainMenu = 'playMainMenu_en';
}

var env;
try {
    if (mainMenuInput == '1') {
        routingOption = 'new_order';
    } else if (mainMenuInput == '2') {
        routingOption = 'follow_up';
    } else {
        routingOption = 'invalid';
    }
    env.info("Routing option selected: " + routingOption);
    hangupAt = 'PostMainMenuScript';
} catch(e) {
    env.info("Error in PostMainMenuScript: " + e);
    routingOption = 'error';
}

var env;
try {
    transferTo = 'sip:xceed@callcenter.com';
    env.info("Setting transfer destination to Xceed: " + transferTo);
    hangupAt = 'SetTransferXceed';
} catch(e) {
    env.info("Error in SetTransferXceed script: " + e);
}

var env;
try {
    transferTo = 'sip:voicebot@exotel.com';
    env.info("Setting transfer destination to Voice Bot: " + transferTo);
    hangupAt = 'SetTransferBot';
} catch(e) {
    env.info("Error in SetTransferBot script: " + e);
}

var env;
try {
  env.info("Max tries have been exceeded. The call will now be terminated.");
} catch(e) {
  env.info("Error in PlayMaxTries script: " + e);
}
